   "orig": "Bristol Old Vic tackles arts ‘emergency’ by bringing the theatre into classrooms",
   "lead": "La compagnia teatrale Bristol Old Vic risponde a quella che definisce un'«emergenza» per le arti portando spettacoli gratuiti nelle scuole. Famiglie e istituti scolastici hanno bilanci sempre più ridotti, e l'obiettivo è rendere il teatro accessibile a più ragazzi. Alla City Academy di Bristol sei giovani attori hanno messo in scena uno spettacolo costruito attorno a una domanda: che cosa significa essere giovani in Gran Bretagna nel 2026? Lo riferisce The Guardian.",
