   "sez": "ambiente",
   "titolo": "Giornata mondiale dell'alimentazione, centinaia di manifestanti davanti al Parlamento sudafricano",
   "orig": "WORLD FOOD DAY: Hundreds of protesters take on Parliament: ‘Wake up, the climate emergency is here!’",
   "lead": "In occasione della Giornata mondiale dell'alimentazione, centinaia di persone hanno marciato fino al Parlamento del Sudafrica, a Città del Capo. I manifestanti chiedevano giustizia alimentare, sovranità alimentare, interventi contro la crisi climatica, il divieto dei pesticidi e preparativi urgenti in vista di El Niño. Lo slogan era: «Svegliatevi, l'emergenza climatica è qui!». Lo riferisce Daily Maverick.",
   "more": [
    "El Niño è un fenomeno climatico che riscalda periodicamente le acque del Pacifico. Nell'Africa australe è spesso associato a siccità che danneggiano i raccolti."
   ],
