   "orig": "Village Installs Knitted Traffic Cops to Slow Down Speeding Drivers",
   "lead": "A Fillongley, un villaggio del Warwickshire, in Inghilterra, alcuni abitanti hanno realizzato a maglia autovelox e vigili a grandezza naturale per scoraggiare chi guida troppo veloce. I manichini, preparati dal gruppo locale Knit and Natter, indossano giubbotti ad alta visibilità per sembrare veri agenti del traffico. L'obiettivo è ridurre gli incidenti. Lo riferisce Good News Network.",
