   "sez": "sport",
   "titolo": "Pallavolo, a Kinshasa al via la 22ª Coppa del Congo",
   "orig": "Volley-ball : début de la 22e édition de la Coupe du Congo ce samedi à Kinshasa",
   "lead": "Sabato 17 ottobre è cominciata a Kinshasa la 22ª edizione della Coppa del Congo di pallavolo. Le gare si disputano nella palestra della Polizia nazionale congolese, nella capitale della Repubblica Democratica del Congo. Nella giornata inaugurale si sono giocati i primi incontri sia del torneo femminile sia di quello maschile, che hanno già prodotto i loro risultati. La competizione proseguirà nei prossimi giorni con le altre partite in programma. Lo riferisce Radio Okapi.",
