   "titolo": "Gand ricorda i 30 anni della Marcia Bianca",
   "orig": "Herdenking van 30 jaar Witte Mars in Gent: \"Spijt dat ik toen niet meestapte\"",
   "lead": "Alcune decine di persone si sono riunite a Gand, in Belgio, per commemorare la Marcia Bianca, che trent'anni fa attraversò le strade di Bruxelles. Il corteo è partito dal Belfort, la torre civica della città, ed è arrivato al palazzo di giustizia, fermandosi in alcuni luoghi legati ai fatti e ai ricordi di quella mobilitazione. Tra i partecipanti c'era chi ha detto di rimpiangere di non aver marciato allora. Lo riferisce VRT NWS.",
