   "sez": "manga",
   "titolo": "Touka racconta la nuova sigla dell'anime «Magic Knight Rayearth»",
   "orig": "Singer-Songwriter Touka on Creating the New Magic Knight Rayearth Anime Opening",
   "lead": "La cantautrice Touka ha parlato della creazione della sigla d'apertura del nuovo anime di «Magic Knight Rayearth». L'artista ha firmato la canzone che accompagna il ritorno sullo schermo di questa storica serie, un'occasione per tornare nel suo mondo fantastico. Le fonti non forniscono ulteriori dettagli sui contenuti dell'intervista né sulla data di uscita della nuova produzione animata. Lo riferisce Crunchyroll News.",
   "more": [
    "«Magic Knight Rayearth» è un manga del collettivo di autrici Clamp, pubblicato negli anni Novanta e diventato anche una popolare serie animata. Racconta di tre ragazze trasportate in un mondo magico per salvarlo. In Italia l'anime è stato trasmesso con il titolo «Una porta socchiusa ai confini del sole»."
   ],
