   "sez": "manga",
   "titolo": "«Romelia War Chronicle», due nuovi nomi nel cast dell'anime",
   "orig": "Romelia War Chronicle Anime Adds Two New Cast Members",
   "lead": "L'adattamento animato di «Romelia War Chronicle» allarga il proprio cast con due nuovi doppiatori. La serie è tratta dalla saga di light novel fantasy firmata da Ryo Ariyama ed è distribuita in streaming dalla piattaforma Crunchyroll. L'annuncio arricchisce la squadra di voci che darà vita ai personaggi dell'opera, mentre prosegue la promozione della trasposizione. La fonte non precisa i nomi dei nuovi interpreti né i ruoli che ricopriranno. Lo riferisce Crunchyroll News.",
   "more": [
    "Le light novel sono romanzi brevi giapponesi, spesso corredati da illustrazioni in stile manga, e rappresentano una delle principali fonti di soggetti per l'animazione nipponica. Gli studi annunciano di frequente i doppiatori in più tappe, per mantenere vivo l'interesse del pubblico nei mesi che precedono e accompagnano la messa in onda."
   ],
