   "titolo": "Bahrein, il Riffa vince largo il derby e va in testa",
   "orig": "Riffa Go Top With Derby Rout",
   "lead": "Nel campionato di calcio del Bahrein il Riffa ha travolto i rivali nel derby e si è preso il primo posto in classifica. Nella stessa giornata l'Hidd ha evitato la sconfitta grazie a un gol segnato in pieno recupero, che gli ha permesso di portare a casa un punto. La testata non riporta nel titolo i punteggi delle due partite. Lo riferisce Daily Tribune (Bahrein).",
