   "lead": "Il Wilberforce Strikers continua il suo ottimo inizio di stagione nella Premier League della Sierra Leone. La squadra ha battuto 3-1 il Bo Rangers, campione in carica, con una vittoria netta che le vale il primo posto in classifica. Il successo contro i detentori del titolo conferma la buona partenza della formazione nel campionato nazionale. Lo riferisce Sierraloaded.",
