   "lead": "Nella settima giornata di Serie A è andata in scena una sfida tra calciatori argentini. Nico Paz ha segnato contro la Fiorentina con un colpo di testa giudicato perfetto. Nella stessa partita ha commesso un fallo sul connazionale Mastantuono, che gli è costato un'ammonizione. Gli episodi sono stati seguiti con attenzione in Argentina. Lo riferisce La Nación.",
