   "orig": "Ekushey Book Fair 2027 to begin on 7 January",
   "lead": "L'edizione 2027 della Fiera del libro Ekushey, in Bangladesh, comincerà il 7 gennaio. È una data diversa da quella tradizionale: la manifestazione di solito si svolge a febbraio. La fiera è uno degli appuntamenti culturali più attesi del Paese e richiama ogni anno editori, autori e lettori. La fonte non fornisce altri dettagli sull'organizzazione dell'evento. Lo riferisce Prothom Alo (inglese).",
