   "orig": "Bolívar y Always Ready defienden la punta en difíciles visitas",
   "lead": "In Bolivia si chiude la ventiduesima giornata del campionato di calcio. Il Bolívar, detto \"la Academia\", e l'Always Ready, \"la banda roja\", sono appaiati in testa alla classifica con 48 punti ciascuno. Entrambe affrontano trasferte complicate e non possono permettersi passi falsi se vogliono continuare la loro corsa a due per il titolo. Lo riferisce Brújula Digital.",
