   "lead": "Il pioniere cinese della realtà aumentata Rokid ha aperto a Hong Kong il suo nuovo flagship store. Qui i clienti non trovano commessi, ma schermi e un sistema robotico all'uscita. Possono provare gli occhiali smart con intelligenza artificiale, pagare su uno schermo e ricevere il dispositivo da una macchina automatica. L'azienda definisce l'esperimento di vendita «terra di nessuno». Lo riferisce South China Morning Post.",
