   "titolo": "Filip Stankovic, il portiere che ha parato il rigore a De Bruyne",
   "orig": "Filip Stankovic, chi è il portiere che ha parato il rigore a De Bruyne: età, altezza, stipendio, carriera, il papà ex Inter e il fratello in nerazzurro",
   "lead": "Filip Stankovic è stato il protagonista di Venezia-Napoli, partita della settima giornata di Serie A. Il portiere del Venezia, figlio dell'ex centrocampista dell'Inter Dejan Stankovic e fratello di un giocatore nerazzurro, ha neutralizzato un calcio di rigore calciato da Kevin De Bruyne e firmato una serie di interventi decisivi. La sua prestazione lo ha reso l'uomo copertina della giornata. Lo riferisce Il Messaggero.",
   "more": [
    "Dejan Stankovic è stato un centrocampista serbo che con l'Inter ha vinto numerosi trofei, tra cui la Champions League del 2010. Kevin De Bruyne, centrocampista belga a lungo stella del Manchester City, è approdato al Napoli. Parare un rigore a un tiratore di questo livello è un'impresa che fa notizia."
   ],
