   "sez": "mondo",
   "titolo": "Crolla in parte un edificio di cinque piani ad Abuja, un ferito",
   "orig": "One injured as five-storey building collapses in Abuja",
   "lead": "Ad Abuja, la capitale della Nigeria, un edificio di cinque piani in costruzione è crollato parzialmente nel quartiere di Wuse II. Una persona ha riportato ferite lievi. L'episodio è stato segnalato dall'agenzia nazionale per la gestione delle emergenze. Al momento non sono note le cause del cedimento della struttura. Lo riferisce The Punch.",
   "more": [
    "In Nigeria i crolli di edifici, spesso ancora in costruzione, sono un problema ricorrente. Le cause indicate più spesso sono l'uso di materiali scadenti, il mancato rispetto delle norme edilizie e controlli insufficienti nei cantieri."
   ],
