   "id": "z2aee98ff",
   "sez": "adolescenti",
   "titolo": "Supplenze 2026/27, continuano gli interpelli per trovare insegnanti",
   "orig": "Supplenze 2026/27: sempre nuovi interpelli alla ricerca di insegnanti",
   "lead": "Per l'anno scolastico 2026/27 molte scuole italiane continuano a pubblicare interpelli per trovare docenti. Si cercano insegnanti anche per supplenze lunghe, fino al 30 giugno e fino al 31 agosto. L'elenco degli avvisi viene aggiornato ogni giorno. Agli interessati si consiglia di consultare anche le pagine degli Uffici scolastici, dove sono disponibili i dettagli delle singole richieste. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Gli interpelli sono avvisi con cui le scuole cercano supplenti quando le graduatorie disponibili sono esaurite. Possono rispondere anche aspiranti docenti che non sono inseriti in quelle graduatorie, purché abbiano i titoli richiesti."
   ],
